def rle(s: str) -> str:
    if not s:
        return ""
    result = []
    count = 0
    current_char = s[0]
    for char in s:
        if char == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = char
            count = 1
    result.append(f"{current_char}{count}")
    return "".join(result)
```

